 if unexpected:raise RuntimeError("UNOWNED_SOURCE_DIFF_DENIED")
 git("merge","--ff-only","origin/main")
 after=git("rev-parse","HEAD")
 if after!=target:raise RuntimeError("FF_HEAD_INVALID")
 ledger=Path("/home/admin1/logs/servercore-service-deploy")/(RID+".json")
 if not ledger.is_file():raise RuntimeError("SOURCE_LEDGER_MISSING")
 data=json.loads(ledger.read_text())
 raw=data.get("stdout")
 if (data.get("request_id")!=RID or data.get("state")!="HOST_COMMAND_PASS"
