       "original_stdout_sha256":hashlib.sha256(b).hexdigest(),
       "original_stderr_bytes":len(str(data.get("stderr") or "").encode("utf-8")),
       "ledger_recovery":"VERIFIED","private_payload_published":False}
 p=subprocess.run(["gh","api","-X","POST","repos/G-ACE-inc/server-core/issues/40/comments","--input","-","--jq",".html_url"],
 input=json.dumps({"body":"AGENT_POOL_PR300_HOST_RECOVERY\n"+json.dumps(info,indent=2)}),capture_output=True,text=True,timeout=20)
 print("AGENT_POOL_PR300_HOST_RECOVERY="+json.dumps({**info,"recorded":p.returncode==0}))
except Exception as exc:
 print("AGENT_POOL_PR300_RECOVERY_FAILED="+str(exc)[:100])
